def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # Fill the enclosed pocket made by the long crossing outlines; small
    # incidental cavities where outlines merely meet remain unfilled.
    seen = set()
    out = [row[:] for row in grid]
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != background or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            component = []
            touches_edge = False
            while q:
                r, c = q.popleft()
                component.append((r, c))
                if r in (0, h - 1) or c in (0, w - 1):
                    touches_edge = True
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == background:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if not touches_edge:
                rs = [r for r, _ in component]
                cs = [c for _, c in component]
                # A genuine interior cavity spans both axes and has area > 3;
                # tiny pockets at stripe intersections are incidental.
                if len(component) > 3 and max(rs) > min(rs) and max(cs) > min(cs):
                    for r, c in component:
